-- =====================================================================
-- STEP 86. Safe to run twice.
-- ---------------------------------------------------------------------
-- 1. INTERNAL FORMS: a cover picture per form, and what each answer
--    owes (worked out by the internal-forms function from what the
--    member ordered, and kept so a later price change never rewrites an
--    order already placed).
-- 2. A SAFETY NET for step 85: the private bucket for the forms' files
--    and pictures, and the stored receipt email. The copy of the step 85
--    migration that ran created the tables only.
-- 3. ONLINE EVENTS: the meeting link in a box nobody can miss, in the
--    registration confirmation and in the email that gives a place from
--    the waiting list. The templates are the responsive output of
--    transactional-emails.ts, as for every other template.
-- =====================================================================

-- ── 1. Internal forms ────────────────────────────────────────────────
ALTER TABLE public.internal_forms ADD COLUMN IF NOT EXISTS cover_path text;
ALTER TABLE public.internal_form_responses ADD COLUMN IF NOT EXISTS amount_due numeric(10, 2);

-- ── 2. Safety net ────────────────────────────────────────────────────
INSERT INTO storage.buckets (id, name, public, file_size_limit)
VALUES ('internal-forms', 'internal-forms', false, 10485760)
ON CONFLICT (id) DO NOTHING;

